We claim the largest value of  $p = \boxed{7}$ , and the necessary constructions are:  $\boxed{(1, 2, 3, 5, 6, 7, 8)}$ ,  $\boxed{(1, 2, 3, 4, 6, 7, 9)}$ ,  $\boxed{(1, 2, 3, 4, 5, 8, 9)}$ , and  $\boxed{(1, 2, 3, 4, 5, 7, 10)}$ .

Due to size constraints, \[\dfrac{p(p+1)}{2} \le a_1+a_2+\dots+a_p \le 32.\] Hence, we have that  $p \le \boxed{7}$ .

We will now find all possible constructions for  $p = 7$ . Clearly, they are:  $(1, 2, 3, 5, 6, 7, 8)$ ,  $(1, 2, 3, 4, 6, 7, 9)$ ,  $(1, 2, 3, 4, 5, 8, 9)$ ,  $(1, 2, 3, 4, 5, 7, 10)$ , and  $(1, 2, 3, 4, 5, 6, 11)$ . Clearly, the last one cannot work due to the size of the  $11$  rectangle. We have constructions for the other four:
[asy]
int N = 4;
int cols = 2;
real cell = 0.7cm;
real gap = 0.8cm;
pen gridLine = gray(0.8);
pen border = black+linewidth(0.7);

real gridSize = 8*cell;
real pitchX = gridSize + gap;
real pitchY = gridSize + gap;

int rows = ceil(N/(real)cols);
real canvasW = cols*pitchX - gap;
real canvasH = rows*pitchY - gap + 0.6cm;
size(canvasW, canvasH);

pair gridOrigin(int i){
  int col = i % cols;
  int row = floor(i / (real)cols);
  pair topLeft = (0, 0);
  return topLeft + (col*pitchX, -row*pitchY);
}

void drawGrid(pair O){
  for(int i=0;i<=8;++i){
    draw(O + (i*cell, 0) -- O + (i*cell, 8*cell), gridLine);
    draw(O + (0, i*cell) -- O + (8*cell, i*cell), gridLine);
  }
  draw(O -- O + (8*cell,0) -- O + (8*cell,8*cell) -- O + (0,8*cell) -- cycle, border);
}

for(int i=0;i<N;++i){
  pair O = gridOrigin(i);
  drawGrid(O - (0, gridSize));
}

void drawRectOnGrid(int idx, int x1, int y1, int x2, int y2, pen p=currentpen, string number="", real alpha=0.18){
  pair Otop = gridOrigin(idx);
  pair O = Otop - (0, gridSize);
  int xl = min(x1,x2);
  int xr = max(x1,x2);
  int yb = min(y1,y2);
  int yt = max(y1,y2);
  pair A = O + ((xl-1)*cell, (yb-1)*cell);
  pair B = O + ((xr)*cell, (yt)*cell);
  path rect = A -- (B.x, A.y) -- B -- (A.x, B.y) -- cycle;
  draw(rect, p + linewidth(2));
  if(number != ""){
    pair center = (A + B)/2;
    label(number, center, fontsize(10));
  }
}

