\begin{align*}
    \dfrac{1}{a^3(b+c)}+\dfrac{1}{b^3(c+a)}+\dfrac{1}{c^3(a+b)}&=\dfrac{(bc)^3}{b+c}+\dfrac{(ca)^3}{c+a}+\dfrac{(ab)^3}{a+b}
    &=\dfrac{(bc)^2}{\dfrac{1}{c}+\dfrac{1}{b}}+\dfrac{(ca)^2}{\dfrac{1}{a}+\dfrac{1}{c}}+\dfrac{(ab)^2}{\dfrac{1}{b}+\dfrac{1}{a}}
    &\overset{\text{Titu}}{\ge}\dfrac{(ab+bc+ca)^2}{2\left(\dfrac{1}{a}+\dfrac{1}{b}+\dfrac{1}{c}\right)}
    &=(ab+bc+ca)^2\cdot\dfrac{abc}{2(ab+bc+ca)}
    &=\dfrac{ab+bc+ca}{2}
    &\overset{\text{AM-GM}}{\ge}\dfrac{3\sqrt[3]{(abc)^2}}{2}
    &=\dfrac{3}{2}
.\end{align*}

Observing that  $a$ ,  $b$ , and  $c$  are positive real numbers satisfying  $abc=1$ , we deduce that there must exist positive numbers  $x$ ,  $y$ , and  $z$  such that  $(a,b,c)=\left(\frac{x}{y},\frac{y}{z},\frac{z}{x}\right).$  Homogenizing, we find that
\begin{align*}
a^3(b+c)&=\left(\frac{x}{y}\right)^3\biggl(\frac{y}{z}+\frac{z}{x}\biggl)
&=\left(\frac{x^3}{y^3}\right)\biggl(\frac{xy+z^2}{xz}\biggl)
&=\frac{x^2(xy+z^2)}{y^3z}
&=\frac{x^3y^2z+x^2yz^3}{y^4z^2}.
\end{align*}

Substituting the above into our cyclic sum and applying Titu's Lemma gives
\begin{align*}
\sum_{\text{cyc}}\frac1{a^3(b+c)}&=\sum_{\text{cyc}}\frac{y^4z^2}{x^3y^2z+x^2yz^3}
&\ge\frac{(y^2z+z^2x+x^2y)^2}{xyz\sum_{\text{cyc}}(x^2y+xz^2)}
&=\frac{(y^2z+z^2x+x^2y)^2}{2xyz(y^2z+z^2x+x^2y)}
&=\frac{y^2z+z^2x+x^2y}{2xyz}
&=\frac12\left(\frac{y}{x}+\frac{z}{y}+\frac{x}{z}\right).
\end{align*}
Since the AM-GM Inequality implies that
\begin{align*}
\frac{y}{x}+\frac{z}{y}+\frac{x}{z}&\ge3\sqrt[3]{\biggl(\frac{y}x\biggl)\biggl(\frac{z}y\biggl)\biggl(\frac{x}y\biggl)}
&=3,
\end{align*}
it follows that   $$ \sum_{\text{cyc}}\frac1{a^3(b+c)}\ge\frac32, $$   as desired. Due to Titu's Lemma and the AM-GM Inequality, we see that equality occurs iff  $x=y=z$ , so that  $a=b=c=1.$   $\blacksquare$ - Jörg

Begin by noticing  $ab+bc+ca \ge 3\sqrt[3]{(abc)^2} =3$ . Then, we have

\begin{align*}
\sum_{\text{cyc}} \frac{1}{a^3(b+c)} &= \sum_{\text{cyc}} \frac{b^2c^2}{a^3b^2c^2(b+c)} 
&= \sum_{\text{cyc}} \frac{(bc)^2}{ab+ac} 
& \ge \frac{(ab+bc+ca)^2}{2(ab+bc+ca)} = \frac{3}{2}. \ \square
\end{align*}

By Titu,
\begin{align*}
\sum_{\text{cyc}} \left(\frac{\left(\frac1a\right)^2}{a(b+c)}\right) &\ge \frac{\left(\frac1a+\frac1b+\frac1c\right)^2}{\sum_{\text{cyc}} a(b+c)}
&=\frac{(ab+bc+ca)^2}{2(ab+bc+ca)}
&=\frac12 (ab+bc+ca),
\end{align*}
so the problem reduces to showing that  $ab+bc+ca \ge 3$ , which is clear.

Here
\begin{align*}
    \sum \frac{1}{a^3 (b + c)} &= \sum \frac{\frac{1}{a^2}}{ab + ac} 
    &\geq \frac{(\sum \frac{1}{a})^2}{2\sum ab}\text{ (by Titu)} 
    &= \frac{(\sum ab)^2}{2a^2 b^2 c^2 \sum ab} 
    &= \frac{\sum ab}{2a^2 b^2 c^2} 
    &= \frac{1}{2} \sum ab 
    &\geq \frac{3}{2}\text{ (by AM-GM)}
\end{align*}
as desired.

Notice that
\begin{align*}
\frac {1}{a^{3}\left(b + c\right)} + \frac {1}{b^{3}\left(c + a\right)} + \frac {1}{c^{3}\left(a + b\right)} &= \frac {a^2b^2c^2}{a^{3}\left(b + c\right)} + \frac {a^2b^2c^2}{b^{3}\left(c + a\right)} + \frac {a^2b^2c^2}{c^{3}\left(a + b\right)} 
&= \frac {b^2c^2}{ab+ac} + \frac {c^2a^2}{bc+ba} + \frac {a^2b^2}{ca+cb}.
\end{align*}
By Titu's Lemma,
\begin{align*}
\frac {b^2c^2}{ab+ac} + \frac {c^2a^2}{bc+ba} + \frac {a^2b^2}{ca+cb} \geq \dfrac{(ab+bc+ca)^2}{2(ab+bc+ca)} = \dfrac{ab+bc+ca}{2}.
\end{align*}
By AM-GM, note that  $ab + bc + ca \geq 3\sqrt[3]{a^2b^2c^2} = 3$ , as desired.

Cauchy gives:
\begin{align*}
  \left(\frac{1}{a^3(b+c)} + \frac{1}{b^3(c+a)} + \frac{1}{c^3(a+b)}\right)(a(b + c) + b(a + c) + c(a + b)) & \geq 9\left(\frac1a + \frac1b + \frac1c\right)^2
\end{align*}
Hence, all that remains is to prove that  $ab + ac + bc \geq 3.$  However, by AM-GM, this is trivial.

For equality, note that in the last step, we used AM-GM. Thus, we have that  $ab = ac = bc,$  and so  $a = b = c,$  and hence  $a = b = c = 1$

By Cauchy-Schwarz, 
\[ \left( \frac{1}{a^{3}(b+c)}+\frac{1}{b^{3}(c+a)}+\frac{1}{c^{3}(a+b)}\right) \ge \frac{\left( \frac{1}{a}^2+\frac{1}{b}^2+\frac{1}{c}^2\right)}{a(b+c)+b(c+a)+c(a+b)}.\]
Now since  $ab+ac+bc = \frac{1}{a}+\frac{1}{b}+\frac{1}{c},$  it suffices to show 
\begin{align*}
\left( \frac{1}{a^{3}(b+c)}+\frac{1}{b^{3}(c+a)}+\frac{1}{c^{3}(a+b)}\right) &\ge \frac{\left( \frac{1}{a}^2+\frac{1}{b}^2+\frac{1}{c}^2\right)}{a(b+c)+b(c+a)+c(a+b)} 
&=\frac{ab+ac+bc}{2}  
&\ge \frac{3}{2}
\end{align*}
which is true by  $\text{AM-GM}. \ \blacksquare$

