draw(circle((0,0),1));
draw(A--B--C--cycle);
draw(O--C);
draw(B--O--P--A);
label(" $A$ ",A,NE);
label(" $B$ ",B,SW);
label(" $C$ ",C,SE);
label(" $O$ ",O,N);
label(" $P$ ",P,S);
[/asy]
Note that  $\angle BOC=2\angle A$  due to the Inscribed Angle Theorem. Since  $\triangle BOC$  is isosceles with  $BO=OC$ , it follows that
\begin{align*}
\angle OBC&=\angle OCB
&=\frac{180^{\circ}-\angle BOC}2
&=\frac{180^{\circ}-2\angle A}2
&=90^{\circ}-\angle A.
\end{align*}
Thus, proving that  $\angle A+\angle COP<90^{\circ}$  is equivalent to proving that  $\angle COP<90^{\circ}-\angle A=\angle OCP.$  Applying the Law of Sines, we find that  $\frac{OP}{\angle OCP}=\frac{PC}{\angle COP}$ , so that   $$ \frac{OP}{PC}=\frac{\sin\angle OCP}{\sin\angle COP}. $$   If  $OP<PC$ , then  $\sin\angle OCP<\sin \angle COP$  and  $\angle COP<\angle OCP$ , implying that  $\angle OCP+\angle COP>180^{\circ}$ , a contradiction. It therefore follows that having  $\angle A+\angle COP<90^{\circ}$  is equivalent to  $\angle COP<\angle OCP$ , which in turn is the same as having  $PC<OP$ , as proven above. Thus, it suffices to show that  $PC<OP.$ Defining the side lengths  $(BC,CA,AB)=(a,b,c)$ , as usual, we note that   $$ PC=b\cos\angle C $$  by analysis on  $\triangle ACP.$  Moreover, applying the Law of Cosines on  $\triangle OCP$  gives
\begin{align*}
OP^2&=OC^2+CP^2
&=OC^2+CP^2-2OC\cdot CP\cos\angle OCP
&=PC^2+R^2-2R(b\cos\angle C)\cos(90^{\circ}-\angle A)
&=PC^2+R^2-2Rb\cos\angle C\sin\angle A,
\end{align*}
where  $R=OA=OB=OC$  is the circumradius of  $\angle ABC.$ Now, note that  $R=\frac{b}{2\sin\angle B}$  by the Law of Sines, it follows that
\begin{align*}
\frac{2(OP^2-PC^2)\sin\angle B}{bR}&=\frac{2R\sin\angle B-4b\cos\angle C\sin\angle B\sin\angle A}b
&=\frac{b-4b\cos\angle C\sin\angle B\sin\angle A}b
&=1-4b\cos\angle C\sin\angle B\sin\angle A.
\end{align*}
Since  $\frac{2\sin\angle B}{bR}$  is clearly positive, we see that  $\frac{2(OP^2-PC^2)\sin\angle B}{bR}=1-4b\cos\angle C\sin\angle B\sin\angle A$  and  $OP^2-PC^2$  share the same sign. Thus, to prove that  $PC<OP$ , it suffices to show that  $\cos\angle C\sin\angle B\sin\angle A<\frac14.$ \paragraph{}Note that  $\sin\angle A<1$  due to the acuity of  $\angle ABC$ ; in addition, the fact that  $\angle C\ge\angle B+30^{\circ}$  implies that  $\cos\angle C\le\cos(\angle B+30^{\circ})$  as the cosine function is decreasing on the range  $[0^{\circ},180^{\circ}].$  Therefore
\begin{align*}
\cos\angle C\sin\angle B\sin\angle A&<\cos\angle C\sin\angle B
&\le\cos(\angle B+30^{\circ})\sin\angle B
&=\sin(90^{\circ}-(\angle B+30^{\circ})\sin\angle B
&=\sin(60^{\circ}-\angle B)\sin\angle B.
\end{align*}
Applying the Sum-to-Product Identity for products of sines, we find that
\begin{align*}
\cos\angle C\sin\angle B\sin\angle A&<\sin(60^{\circ}-\angle B)\sin\angle B
&=\frac{\cos((60^{\circ}-\angle B)-\angle B)-\cos((60^{\circ}-\angle B)+\angle B)}2
&=\frac{\cos(60^{\circ}-2\angle B)-\cos60^\circ}2
&\le\frac{1-\frac12}2
&=\frac14,
\end{align*}
as desired.  $\blacksquare$

Let  $D$  be the second intersection of  $CO$  and  $(ABC)$ . Now, notice that 
\begin{align*}
    \angle CAB + \angle COP &< 90^\circ
    \angle COP &< 90-\angle CAB
    \angle COP &< \angle DAB 
    \angle COP &< \angle DCB = \angle OCP
\end{align*}
Thus, the required conclusion rewrites to showing  $\angle COP < \angle OCP$  or in turn  $PC < OP$ .
Now, let  $X = \overline{OC} \cap \overline{AP}$ . First, notice that 
\[PC < XC \text{ ( $\angle XPC= 90^\circ$  and thus  $\angle PXC < 90$ )}\]
Next by Ratio Lemma,
\begin{align*}
    \frac{OX}{XC} &= \frac{AO}{AC} \cdot \frac{\sin{\angle OAP}}{\sin{\angle PAC}}
    OX &= \left( \frac{AO}{AC}\cdot \frac{\sin{\angle OAP}}{\sin{\angle PAC}} \right) XC.
\end{align*}
Now, 
\begin{align*}
    \frac{AO}{AC}\cdot \frac{\sin{\angle OAP}}{\sin{\angle PAC}} &= \frac{\sin{\angle OCA}}{\sin{\angle AOC}}\cdot \frac{\sin{\angle OAP}}{\sin{\angle PAC}} 
    &= \frac{\sin{90-\angle B}}{\sin{\angle B}} \cdot \frac{\sin{\angle B + \angle C}}{\sin{90-\angle C}}
    &= \left(\frac{BP}{AB}\cdot\frac{AC}{PC}\right) \left(\frac{\frac{AP}{AB}\cdot\frac{PC}{AC}+\frac{AP}{AC}\cdot\frac{BP}{AB}}{2\cdot \frac{AP}{AB}\cdot\frac{BP}{AB}}\right)
    &= \frac{PC+BP}{2PC} > 1
\end{align*}
since  $A$  is closer to  $C$  than  $B$  ( $\angle BCA > \angle ABC$ ) and  $P$  is the foot of the altitude. Further,   $$ \angle OXP = 90 + \angle OCP > \angle OPA \text{ (this angle is strictly less than  $90^\circ$ )} $$  So,  $OX< OP$  as well. Thus, we have that 
\[PC < XC < OX < OP\]
and thus,  $PC < OP$  as needed.

Let  $Q$  be the intersection point of  $OC$  and  $AP$ . We find  $\angle OAP = C-B \geq 30^{\circ}$ . Moreover  $\angle PAC=90^{\circ}-C$ . The Sine rule applied to triangles  $AOQ$  and  $CAQ$  imply  $\frac{OQ}{\sin(C-B)} = \frac{R}{\sin \angle OQA}$  and  $\frac{QC}{\sin (90^{\circ}-C)} = \frac{2R \sin B}{\sin \angle CQA}$ , respectively, where  $R$  is the circumradius of triangle  $ABC$ . Hence
\[\frac{OQ}{QC} = \frac{\sin(C-B)}{2\sin B \cos C}>1,\]
because  $\sin (C-B)>2\sin B \cos C \Leftrightarrow \sin(C-B)> \sin(B-C) + \sin(B+C) \Leftrightarrow 2 \sin (C-B)>\sin(B+C)$  which is true since  $2 \sin (C-B) \geq 2 \sin 30^{\circ} = 1 > \sin (B+C)$ .

Lastly, from the Sine rule applied to triangles  $OPQ$  and  $PQC$  we get  $\frac{OP}{\sin \angle OQP} = \frac{OQ}{\sin \angle OPQ}$  and  $\frac{PC}{\sin \angle PQC} = \frac{QC}{\sin \angle CPQ}$  where 
\[\frac{OP}{PC} = \frac{\sin \angle CPQ}{\sin \angle OPQ} \cdot \frac{OQ}{QC}.\]
As  $\triangle ABC$  is acute-angled,  $O$  is an interior point of  $\triangle ABC$ . In fact,  $\angle OPC < 180^{\circ}$  so  $\angle OPQ < \angle CPQ$ . In other words, the two ratios in the equation above must be  $>1$  and consequently,  $OP>PC$ . We are done.
