pair K5 = (6,1); pair K6 = (6,-1);
draw(K1--K5, palered); draw(K2--K5, palered); draw(K3--K5, palered); draw(K4--K5, palered);
draw(K1--K6, palered); draw(K2--K6, palered); draw(K3--K6, palered); draw(K4--K6, palered);
pair B1 = (4.8,1.3); pair B2 = (3.7,0); pair B3 = (4.8,-1.3);
pair C1 = (7.2,1.3); pair C2 = (8.3,0); pair C3 = (7.2,-1.3);
draw(K5--B1--K6, paleblue); draw(K5--B2--K6, paleblue); draw(K5--B3--K6, paleblue); draw(B1--B2--B3--cycle, paleblue); draw(K5--C1--K6, paleblue); draw(K5--C2--K6, paleblue); draw(K5--C3--K6, paleblue); draw(C1--C2--C3--cycle, paleblue);
draw(K1--K2--K3--K4--cycle, red+1); draw(K1--K3, red+1); draw(K2--K4, red+1); draw(K5--K6, red+1);
